    // ---- คุณสมบัติฉาก ----
    const chP = (await kapi.readJson(await kapi.join(dPath, 'draft.json'))).chapters[0];
    const scP = (await kapi.readJson(await kapi.join(dPath, 'scenes.json'))).chapters[chP.guid][0];
    const pProps = sceneProps(dPath, chP, scP);
