        await until62(() => pane7.scrollHeight > pane7.clientHeight + 400);
        check('[62-7] เนื้อหายาวพอให้เลื่อนได้จริง', pane7.scrollHeight > pane7.clientHeight + 400,
              `${pane7.scrollHeight} / ${pane7.clientHeight}`);
