        pane7.scrollTop = 400;
        await until62(() => pane7.scrollTop === 400, 20, 30);
        const keep7 = pane7.scrollTop;
        check('[62-7] ตั้งตำแหน่งเลื่อนแล้วติดทันที', keep7 === 400, String(keep7));

        const other7 = isPanelOpen('log') ? 'notes' : 'log';
        showPanel(other7);
